// Generates the markdown documents of handoff/TRADE_ECONOMICS_V5 from results/v5_results.json.
import { readFileSync, writeFileSync, mkdirSync, copyFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
const HERE = dirname(fileURLToPath(import.meta.url)); const REPO = join(HERE, '..', '..', '..'); const ROOT = join(REPO, 'research', 'trade_economics_v5'); const R = JSON.parse(readFileSync(join(ROOT, 'results', 'v5_results.json'), 'utf8')); const DEFN = R.finalist_definitions; const OUT = join(REPO, 'handoff', 'TRADE_ECONOMICS_V5'); mkdirSync(OUT, { recursive: true });
const f = (x, d = 3) => (x == null ? '—' : typeof x === 'number' ? (Number.isInteger(x) ? String(x) : x.toFixed(d)) : String(x)); const ci = (c) => (c ? `[${f(c[0])}, ${f(c[1])}]` : '—'); const pc = (x) => (x == null ? '—' : `${(x * 100).toFixed(1)} %`); const S2 = ['DEV', 'HOLD']; const W = (name, md) => writeFileSync(join(OUT, name), md);
const MEAN = R.meta.meaningful; const ALLPOP = Object.keys(R.meta.populations); const FAMS = ['FIXED', 'BE', 'PARTIAL', 'FLOOR', 'HARVEST', 'STRUCT_TRAIL', 'TIME']; const POPNAME = { CONTROL: 'CONTROL (production entries)', S1: 'S1 compression→expansion', S2: 'S2 sweep→reclaim', S3: 'S3 first structure break', S4: 'S4 pullback→continuation', S5: 'S5 momentum ignition', S6: 'S6 range break', S7: 'S7 trend resumption' };
const DEC = R.decisions; const HC = R.finalists.HOLD.CONTROL.CONTROL_EXIT; const BEST = DEC.best; const HB = R.finalists.HOLD[BEST.pop][BEST.family]; const DB = R.finalists.DEV[BEST.pop][BEST.family]; const ctlKey = (pop) => (pop === 'CONTROL' ? 'CTL|PROD_TP2' : 'FIXED|rr1.7');
const cellRow = (k, v) => `| ${k} | ${v.n}${v.n < 30 ? ' (INSUFFICIENT)' : ''} | ${pc(v.win_rate)} | ${f(v.avg_win_r, 2)} / ${f(v.avg_loss_r, 2)} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 1)} | ${f(v.mfe_r, 2)} / ${f(v.mae_r, 2)} | ${f(v.median_bars)} | ${ci(v.ci95_r)} |`; const CELLH = '| Segment | N | Win | Avg win / loss (R) | Exp (R) | PF | DD (R) | MFE / MAE (R) | Median bars | 95 % CI |\n|---|---|---|---|---|---|---|---|---|---|';
const POLH = '| Policy | Signals | Trades | Win | Avg win (R) | Avg loss (R) | Exp (R) | Exp (USD @0.01) | PF | Max DD (R) | Median bars | Give-back (R, MFE ≥ 0.5) | Loss streak | Cost USD/trade | Exit mix |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|';
const polRow = (v, label) => `| ${label ?? v.key} | ${v.signals} | ${v.n} | ${pc(v.win_rate)} | ${f(v.avg_win_r, 2)} | ${f(v.avg_loss_r, 2)} | ${f(v.expectancy_r)} | ${f(v.expectancy_usd, 2)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 1)} | ${f(v.median_bars)} | ${f(v.giveback_r_mean, 2)} | ${v.max_loss_streak} | ${f(v.cost_usd, 2)} | ${Object.entries(v.exit_mix).map(([a, b]) => `${a} ${pc(b)}`).join(', ')} |`;
const gridTable = (pop, S, filter = () => true) => `${POLH}\n${Object.entries(R[S].grid[pop]).filter(([k]) => filter(k)).map(([k, v]) => polRow(v, k === ctlKey(pop) ? `${k} (CONTROL EXIT)` : k)).join('\n')}`;

// ---------- control baseline / provenance ----------
W('V5_CONTROL_BASELINE.md', readFileSync(join(ROOT, 'V5_CONTROL_BASELINE.md'), 'utf8') + `\n## Reproduction (asserted by the study)\n| Split | Population | Control exit | n | Exp (R) | PF | DD (R) |\n|---|---|---|---|---|---|---|\n${S2.flatMap((S) => [['CONTROL', 'CTL|PROD_TP2'], ['S3', 'FIXED|rr1.7']].map(([pop, k]) => { const v = R[S].grid[pop][k]; return `| ${S} | ${pop} | ${k} | ${v.n} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 2)} |`; })).join('\n')}\n\ncontrol_reproduces_v4_dev = ${R.meta.controls.control_reproduces_v4_dev}; control_reproduces_v4_hold = ${R.meta.controls.control_reproduces_v4_hold}.\n`);
for (const fn of ['V5_PREREGISTRATION.md', 'V5_PREREGISTRATION.sha256', 'V5_CONTROL_BASELINE.sha256']) copyFileSync(join(ROOT, fn), join(OUT, fn));
W('DATA_PROVENANCE.md', `# DATA PROVENANCE\n\n| Input | Source | Size | Hash reference |\n|---|---|---|---|\n| 5m bars | handoff/edge_discovery_lab/data/XAUUSDm_bars.json (MT5 XAUUSDm, 2025-05-05 → 2026-09-30) | ${R.meta.bars} bars | results/control_inputs.sha256 |\n| Replay rows (regime / session / HTF context) | handoff/edge_discovery_lab/data/lab_rows.jsonl | 99,381 in-range rows | results/control_inputs.sha256 |\n| CONTROL entries with production geometry | research/entry_architecture_v2/results/candidates.jsonl | ${R.meta.populations.CONTROL.all} signals (DEV ${R.meta.populations.CONTROL.dev} / HOLD ${R.meta.populations.CONTROL.hold}) | results/control_inputs.sha256 |\n| V4 entry populations | regenerated by scripts/v4_populations.mjs (verbatim V4 feature/generator code) from research/entry_core_v4/configs/finalists.json (sha ${R.meta.v4_finalists_sha256.slice(0, 16)}…) | ${ALLPOP.filter((p) => p !== 'CONTROL').map((p) => `${p} ${R.meta.populations[p].all}`).join(', ')} | results/control_inputs.sha256 (28 lines) |\n| Re-entry guard | src/engine/capitalHarvest/positionManager.js canReenter (pure, unwired) | — | repo HEAD |\n\nSplit: DEV ${R.meta.split.dev.join(' → ')} (${R.meta.sessions_dev} sessions), HOLDOUT ${R.meta.split.hold.join(' → ')} (${R.meta.sessions_hold} sessions). Costs ${JSON.stringify(R.meta.costs)}; swap −0.56 USD per BUY night; horizon 288 bars; SL before TP on the same bar; broker fail-safe 1.5 × structural + spread intrabar; raised stops are hard intrabar levels from the bar after they are set. 1R = planned |entry − SL| of each trade; USD at 0.01 lot = R × risk distance (1.00 USD per price unit). No live data was captured; no process was touched.\n`);

// ---------- normalisation / entry location / stop ----------
{ let md = `# ENTRY LOCATION ANALYSIS (1R = planned structural risk; control exit; independent signals; EARLY < 0.3 / VALID 0.3–1.0 / LATE 1.0–1.5 / CHASED > 1.5 ATR displacement from the 12-bar origin)\n\n## Trade normalisation\n| Split | Population | N | Risk USD median (p10–p90) | Risk / ATR median (p10–p90) | Target (R) median (p10–p90) | Cost (R) mean | Duration bars median (p90) | USD per 1R at 0.01 lot |\n|---|---|---|---|---|---|---|---|---|\n`; for (const S of S2) for (const pop of ALLPOP) { const n = R[S].diagnostics[pop].normalisation; md += `| ${S} | ${pop} | ${n.n} | ${f(n.risk_usd.median, 2)} (${f(n.risk_usd.p10, 1)}–${f(n.risk_usd.p90, 1)}) | ${f(n.risk_atr.median, 2)} (${f(n.risk_atr.p10, 2)}–${f(n.risk_atr.p90, 2)}) | ${f(n.target_r.median, 2)} (${f(n.target_r.p10, 2)}–${f(n.target_r.p90, 2)}) | ${f(n.cost_r.mean)} | ${n.duration_bars.median} (${n.duration_bars.p90}) | ${f(n.usd_per_r_at_001_lot, 2)} |\n`; }
  for (const S of S2) { md += `\n## ${S} — timing class (control exit) with target reach before invalidation\n| Population | Class | N | Exp (R) | PF | Win | MFE / MAE (R) | Reach 1 R | Reach 1.7 R |\n|---|---|---|---|---|---|---|---|---|\n`; for (const pop of MEAN) for (const [k, v] of Object.entries(R[S].diagnostics[pop].entry_location.timing)) md += `| ${pop} | ${k} | ${v.n} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${pc(v.win_rate)} | ${f(v.mfe_r, 2)} / ${f(v.mae_r, 2)} | ${pc(v.reach_1r)} | ${pc(v.reach_1_7r)} |\n`; md += `\n## ${S} — location terciles (control exit; LOW / MID / HIGH expectancy in R)\n| Population | Feature | Cuts | LOW n / exp | MID n / exp | HIGH n / exp |\n|---|---|---|---|---|---|\n`; for (const pop of MEAN) for (const [k, v] of Object.entries(R[S].diagnostics[pop].entry_location)) { if (k === 'timing' || !v) continue; md += `| ${pop} | ${k.replace('_terciles', '')} | ${v.cuts.map((x) => f(x, 2)).join(' / ')} | ${v.LOW.n} / ${f(v.LOW.expectancy_r)} | ${v.MID.n} / ${f(v.MID.expectancy_r)} | ${v.HIGH.n} / ${f(v.HIGH.expectancy_r)} |\n`; } }
  const c = R.HOLD.diagnostics.CONTROL, s3 = R.HOLD.diagnostics.S3; md += `\n## Reading\n- Production entries are CHASED by the 12-bar-origin definition in ${pc(c.entry_location.timing.CHASED.n / c.normalisation.n)} of cases (HOLD) and V4 first-break entries in ${pc(s3.entry_location.timing.CHASED.n / s3.normalisation.n)}: a confirmation trigger fires 2–3 ATR after the move origin by construction. The few VALID/LATE entries are NOT better (CONTROL VALID ${f(c.entry_location.timing.VALID.expectancy_r)} R vs CHASED ${f(c.entry_location.timing.CHASED.expectancy_r)} R), and target reach before invalidation is the same in every class (≈ ${pc(c.target_reach.overall[1])} reach 1 R, ≈ ${pc(c.target_reach.overall[1.7])} reach 1.7 R). Poor expectancy is therefore not "correct setup entered too late": entering earlier does not raise the reach of the target or lower the stop reach.\n- The location features that matter are the stop, not the trigger: wider structural risk (risk/ATR HIGH tercile ${f(c.entry_location.risk_atr_terciles.HIGH.expectancy_r)} R vs LOW ${f(c.entry_location.risk_atr_terciles.LOW.expectancy_r)} R on CONTROL HOLD) and a larger distance to the opposing swing earn more, because tight stops are hit by noise (STRUCTURAL_STOP_ANALYSIS.md). Range position inverts between populations and splits.\n- Verdict: the entry population's economics are set at the trigger (direction, 36–42 % win rate, 54–56 % reach of 1 R before invalidation), not by where inside the move the trigger sits.\n`; W('ENTRY_LOCATION_ANALYSIS.md', md); }
{ let md = `# STRUCTURAL STOP ANALYSIS (diagnosis, not optimisation; control exit unless stated)\n\n| Split | Population | SL / ATR median (p10–p90) | Stop reach (close or broker) | Broker 1.5 R intrabar | Thesis close | Winners with MAE ≥ 0.25 / 0.5 / 0.75 / 1.0 R | Winners MAE-3-bar median | Losers MAE-3-bar median | p90 MAE within 3 bars (all) | SL × 0.75 (R re-normalised): n / exp / PF / win | SL × 1.25: n / exp / PF / win |\n|---|---|---|---|---|---|---|---|---|---|---|---|\n`; for (const S of S2) for (const pop of ALLPOP) { const s = R[S].diagnostics[pop].structural_stop; md += `| ${S} | ${pop} | ${f(s.sl_atr.median, 2)} (${f(s.sl_atr.p10, 2)}–${f(s.sl_atr.p90, 2)}) | ${pc(s.stop_reach_rate)} | ${pc(s.broker_sl_rate)} | ${pc(s.thesis_close_rate)} | ${pc(s.winners_mae_ge[0.25])} / ${pc(s.winners_mae_ge[0.5])} / ${pc(s.winners_mae_ge[0.75])} / ${pc(s.winners_mae_ge[1])} | ${f(s.winners_mae3_median, 2)} | ${f(s.losers_mae3_median, 2)} | ${f(s.noise_mae3_p90_all, 2)} | ${s.sl_scaled[0.75].n} / ${f(s.sl_scaled[0.75].expectancy_r)} / ${f(s.sl_scaled[0.75].pf, 2)} / ${pc(s.sl_scaled[0.75].win_rate)} | ${s.sl_scaled[1.25].n} / ${f(s.sl_scaled[1.25].expectancy_r)} / ${f(s.sl_scaled[1.25].pf, 2)} / ${pc(s.sl_scaled[1.25].win_rate)} |\n`; }
  const c = R.HOLD.diagnostics.CONTROL.structural_stop, s3 = R.HOLD.diagnostics.S3.structural_stop; md += `\n## Reading\n- The production stop sits a median ${f(c.sl_atr.median, 2)} ATR from entry (V4 first-break stops ${f(s3.sl_atr.median, 2)} ATR, at the opposite swing). It is reached in ${pc(c.stop_reach_rate)} of CONTROL trades (${pc(c.broker_sl_rate)} by the 1.5 R broker fail-safe intrabar, ${pc(c.thesis_close_rate)} by a close beyond the structural level) and ${pc(s3.stop_reach_rate)} of S3 trades.\n- **Winners routinely survive adverse excursions that a tighter stop would convert into losses:** half of all CONTROL winners (${pc(c.winners_mae_ge[0.5])}) go ≥ 0.5 R against entry first, a third ≥ 0.75 R, one in six ≥ 1.0 R. Losers' MAE within 3 bars (median ${f(c.losers_mae3_median, 2)} R) is twice the winners' (${f(c.winners_mae3_median, 2)} R), but the distributions overlap heavily; the 90th percentile of 3-bar MAE across all trades is ${f(c.noise_mae3_p90_all, 2)} R — the stop is NOT beyond normal noise, it is inside it for a large minority of trades.\n- Tightening the stop to 0.75 × (R re-normalised) does not help: CONTROL HOLD ${f(c.sl_scaled[0.75].expectancy_r)} R (PF ${f(c.sl_scaled[0.75].pf, 2)}) vs ${f(HC.expectancy_r)} R, DEV ${f(R.DEV.diagnostics.CONTROL.structural_stop.sl_scaled[0.75].expectancy_r)} R — the sign depends on the split; S3 worsens on both splits. Widening to 1.25 × worsens both populations on both splits. The structural stop is approximately at the economic optimum for these entries; its problem is that the entries are wrong 58–64 % of the time, not where the stop is.\n- No SL change is proposed.\n`; W('STRUCTURAL_STOP_ANALYSIS.md', md); }

// ---------- MAE / MFE / reach ----------
{ let md = `# MAE ANALYSIS (maximum adverse excursion in R under the control exit; buckets pre-registered)\n`; for (const S of S2) { md += `\n## ${S}\n| Population | Avg MAE winners | Avg MAE losers | Winners by MAE bucket (0–0.1 / 0.1–0.25 / 0.25–0.5 / 0.5–0.75 / 0.75–1 / 1–1.25 / >1.25) | Losers by bucket | MAE median by side | MAE median by model |\n|---|---|---|---|---|---|---|\n`; for (const pop of MEAN) { const m = R[S].diagnostics[pop].mae; const B = ['0-0.1', '0.1-0.25', '0.25-0.5', '0.5-0.75', '0.75-1', '1-1.25', '1.25-+']; md += `| ${pop} | ${f(m.avg_mae_winners, 2)} | ${f(m.avg_mae_losers, 2)} | ${B.map((b) => m.winners[b]?.n ?? 0).join(' / ')} | ${B.map((b) => m.losers[b]?.n ?? 0).join(' / ')} | ${Object.entries(m.by_side).map(([k, v]) => `${k} ${f(v.mae_median, 2)}`).join(', ')} | ${Object.entries(m.by_model).map(([k, v]) => `${k} ${f(v.mae_median, 2)} (n ${v.n})`).join(', ')} |\n`; } }
  const c = R.HOLD.diagnostics.CONTROL.mae; md += `\n## Reading\nWinners average ${f(c.avg_mae_winners, 2)} R of adverse excursion before winning, losers ${f(c.avg_mae_losers, 2)} R (the broker fail-safe at 1.5 R + spread caps it). The winner distribution is wide: ${pc((c.winners['0.5-0.75']?.n + c.winners['0.75-1']?.n + c.winners['1-1.25']?.n + c.winners['1.25-+']?.n) / Object.values(c.winners).reduce((a, v) => a + v.n, 0))} of CONTROL HOLD winners went more than 0.5 R against entry first. A smaller stop would therefore convert a large share of winners into losses — the "can winners survive a smaller stop?" question is answered NO for every population (the 0.75 × stop diagnostic in STRUCTURAL_STOP_ANALYSIS.md confirms it economically). Side and model differences in MAE are small (medians 1.17–1.49 R) except SR (wider) and MC (narrower); regime differences are within 0.2 R.\n`; W('MAE_ANALYSIS.md', md); }
{ let md = `# MFE ANALYSIS (maximum favourable excursion in R on the OPEN path — structural stop only, no target — and on the control-exit path; pre-registered buckets)\n`; for (const S of S2) { md += `\n## ${S}\n| Population | Open-path MFE bucket counts (<0.25 / 0.25–0.5 / 0.5–0.75 / 0.75–1 / 1–1.25 / 1.25–1.5 / 1.5–1.7 / 1.7–2 / 2–2.5 / >2.5) |\n|---|---|\n`; for (const pop of MEAN) { const m = R[S].diagnostics[pop].mfe.all_open; const B = ['0-0.25', '0.25-0.5', '0.5-0.75', '0.75-1', '1-1.25', '1.25-1.5', '1.5-1.7', '1.7-2', '2-2.5', '2.5-+']; md += `| ${pop} | ${B.map((b) => m[b]?.n ?? 0).join(' / ')} |\n`; } md += `\n| Population | Milestone | All reaching (open path) | Eventual LOSERS reaching | Eventual WINNERS reaching |\n|---|---|---|---|---|\n`; for (const pop of MEAN) for (const m of [0.25, 0.5, 0.75, 1, 1.25, 1.5, 1.7, 2, 2.5, 3]) { const d = R[S].diagnostics[pop].mfe; md += `| ${pop} | ${m} R | ${pc(d.reaching_open[m])} | ${pc(d.losers_reaching_open[m])} | ${pc(d.winners_reaching_open[m])} |\n`; } }
  const c = R.HOLD.diagnostics.CONTROL.mfe, s3 = R.HOLD.diagnostics.S3.mfe; md += `\n## Reading (critical)\n- CONTROL HOLD: ${pc(c.reaching_open[0.5])} of trades reach +0.5 R, ${pc(c.reaching_open[1])} reach +1 R, ${pc(c.reaching_open[1.7])} reach +1.7 R and ${pc(c.reaching_open[2])} reach +2 R before the structural stop. Of the eventual LOSERS, ${pc(c.losers_reaching_open[0.5])} first reached +0.5 R, ${pc(c.losers_reaching_open[1])} reached +1 R and ${pc(c.losers_reaching_open[1.5])} reached +1.5 R (S3: ${pc(s3.losers_reaching_open[0.5])} / ${pc(s3.losers_reaching_open[1])} / ${pc(s3.losers_reaching_open[1.5])}).\n- So roughly a third of losing trades were once +1 R. That is the give-back the exit-policy families attack (PROFIT_GIVEBACK.md, EXIT_POLICY_COMPARISON.md). The flip side is in the winners' column: essentially every winner reached +1 R (by definition) and ${pc(c.winners_reaching_open[2.5])} of CONTROL winners reached +2.5 R — the right tail is where the control exit earns its average winner of ${f(HC.avg_win_r, 2)} R. Protecting the +1 R losers and keeping the +2.5 R winners are the same decision made at the same moment with the same information; the policy results show the trade-off cannot be escaped (RIGHT_TAIL_ANALYSIS.md).\n`; W('MFE_ANALYSIS.md', md); }
{ let md = `# TARGET REACHABILITY (open path: milestone reached before structural invalidation; diagnostic only)\n`; for (const S of S2) { md += `\n## ${S}\n| Population | 0.25 | 0.5 | 0.75 | 1.0 | 1.25 | 1.5 | 1.7 | 2.0 | 2.5 | 3.0 | Stopped before +0.25 R |\n|---|---|---|---|---|---|---|---|---|---|---|---|\n`; for (const pop of ALLPOP) { const d = R[S].diagnostics[pop].target_reach; md += `| ${pop} (n ${R[S].diagnostics[pop].normalisation.n}) | ${[0.25, 0.5, 0.75, 1, 1.25, 1.5, 1.7, 2, 2.5, 3].map((m) => pc(d.overall[m])).join(' | ')} | ${pc(d.stopped_before_any_025)} |\n`; } for (const pop of MEAN) { const d = R[S].diagnostics[pop].target_reach; const sec = (title, obj) => `\n### ${pop} by ${title}\n| Segment | N | Reach 1 R | Reach 1.7 R | Reach 2 R | Stopped before 1 R |\n|---|---|---|---|---|---|\n${Object.entries(obj).map(([k, v]) => `| ${k} | ${v.n} | ${pc(v.reach[1])} | ${pc(v.reach[1.7])} | ${pc(v.reach[2])} | ${pc(v.stopped_before_1r)} |`).join('\n')}\n`; md += sec('model', d.by_model) + sec('direction', d.by_side) + sec('5m regime', d.by_regime) + sec('entry timing', d.by_timing) + sec('ATR state (ATR ratio < 0.8 / 0.8–1.2 / > 1.2)', d.by_atr_state) + sec('session', d.by_session); } }
  const c = R.HOLD.diagnostics.CONTROL.target_reach; md += `\n## Reading\nReach probabilities are remarkably flat across model, direction, regime, timing, ATR state and session: 1 R is reached before invalidation in ${pc(c.overall[1])} of CONTROL trades (range across all segments with N ≥ 100: roughly 50–61 %), 1.7 R in ${pc(c.overall[1.7])} (37–50 %), 2 R in ${pc(c.overall[2])}. With a structural stop that is hit in ~60 % of trades, a fixed target needs reach × (1 + RR) > 1 + loss size to break even; at RR 1.7 the breakeven reach is ≈ 47 % and the observed reach is 41–43 % — the entries are below break-even at every RR tested (RR_GEOMETRY.md). MR (reach 1 R ${pc(c.by_model.MR?.reach[1])}, n ${c.by_model.MR?.n}) and the RANGE / BEAR_TREND regimes are the only segments above 56 %, consistent with V3's small-N leads; nothing is above the break-even reach with a meaningful sample.\n`; W('TARGET_REACHABILITY.md', md); }

// ---------- RR geometry / policies ----------
{ let md = `# RR GEOMETRY (fixed targets 0.5 … 3.0 R on the frozen structural stop; sequential one-position; after NORMAL costs; RR 1.70 = CONTROL reference)\n`; for (const S of S2) for (const pop of MEAN) md += `\n## ${S} — ${POPNAME[pop]}\n${gridTable(pop, S, (k) => k.startsWith('FIXED') || k === ctlKey(pop))}\n`; md += `\n## Reading\nNo fixed target turns any population positive on HOLDOUT with N ≥ 200 except S3 at 3.0 R (+0.048 R, PF 1.06, CI [−0.091, +0.204], SENSITIVE: every other RR negative). Win rate falls from ~70 % at 0.5 R to ~31 % at 3 R exactly as the reach curve predicts, and expectancy stays within ±0.05 R of zero along the whole curve for CONTROL, S2 and S4 — the reach × payoff product is flat and slightly negative everywhere. Small targets (0.5–1.0 R) are the worst because the structural loss (−1.4 R average incl. broker fail-safe and costs) dwarfs the gain. The production objective-based TP2 (median 2.0 R) is not worse than any fixed RR. Target geometry does not contain the edge.\n`; W('RR_GEOMETRY.md', md); }
{ let md = `# EXIT POLICY COMPARISON (B0 control exit, B1 best fixed, B2 milestone protection BE/PARTIAL/FLOOR, B3 structural trail, B4 adaptive harvest, T time-stop; DEV-selected parameter per family; sequential; NORMAL costs)\n`; for (const S of S2) { md += `\n## ${S}\n| Population | Family | Policy | Trades | Win | Avg win / loss (R) | Exp (R) | PF | DD (R) | Trade 95 % CI | Block 95 % CI | Stress exp | Drift exp | Quarters > 0 | Give-back (R) | Right tail ratio / verdict | Δ vs control exit (R) |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|\n`; for (const pop of MEAN) { const F = R.finalists[S][pop]; const ctl = F.CONTROL_EXIT; md += `| ${pop} | B0 | ${ctl.key} (control exit) | ${ctl.n} | ${pc(ctl.win_rate)} | ${f(ctl.avg_win_r, 2)} / ${f(ctl.avg_loss_r, 2)} | ${f(ctl.expectancy_r)} | ${f(ctl.pf, 2)} | ${f(ctl.max_dd_r, 1)} | ${ci(ctl.ci95_r)} | ${ci(ctl.block_ci95_r)} | ${f(ctl.stress.expectancy_r)} | ${f(ctl.drift.expectancy_r)} | ${pc(ctl.quarters_positive_share)} | ${f(ctl.giveback_r_mean, 2)} | 1.00 / YES | — |\n`; for (const fam of FAMS) { const v = F[fam]; if (!v) { md += `| ${pop} | ${fam} | — (no DEV point with N ≥ 200) | | | | | | | | | | | | | | |\n`; continue; } md += `| ${pop} | ${fam} | ${v.key} | ${v.n} | ${pc(v.win_rate)} | ${f(v.avg_win_r, 2)} / ${f(v.avg_loss_r, 2)} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 1)} | ${ci(v.ci95_r)} | ${ci(v.block_ci95_r)} | ${f(v.stress.expectancy_r)} | ${f(v.drift.expectancy_r)} | ${pc(v.quarters_positive_share)} | ${f(v.giveback_r_mean, 2)} | ${f(v.right_tail.ratio, 2)} / ${v.right_tail.verdict} | ${f(v.expectancy_r - ctl.expectancy_r)} |\n`; } } }
  md += `\n## Full policy grids (HOLD)\n`; for (const pop of MEAN) md += `\n### ${POPNAME[pop]}\n${gridTable(pop, 'HOLD')}\n`;
  md += `\n## Reading\n- Milestone protection (break-even, partial, floor) raises the win rate to 50–69 % and cuts drawdown, but leaves expectancy negative or ≈ 0 on every population: the trades it protects (MFE ≥ 0.5–1 R that come back) are offset one-for-one by winners it ejects before the target. Average winner falls from 2.26 R to 0.6–1.0 R.\n- The adaptive harvest (arm 1 R, gap 0.5 R) is the only family that moves expectancy materially: CONTROL entries +0.077 R HOLD (PF 1.13, DD 40 R, win 57 %, avg win 1.16 R) and +0.041 R DEV; S2 +0.061 / +0.031; S4 −0.031 / +0.022; S3 +0.029 / −0.025. It does so by cutting the right tail (mean realized on MFE ≥ 2 R trades 1.29 R vs 1.92 R under the control exit, ratio 0.67, 47 % of tail trades realize < 1 R) and it is NEGATIVE under stress costs on every population (CONTROL −0.012 R) because its exits are many small protected stops that each pay the spread. Its session-block CI includes zero.\n- The structural trail keeps the right tail (ratio 1.1–1.3) and is positive on DEV for CONTROL (+0.113 R) but not on HOLD (+0.022 R, PF 1.02, DD 101 R, tiny-cell dependent); on S2/S3/S4 it is ≈ 0.\n- Time-stops (−0.5 R after 3/6 bars) do nothing: trades at −0.5 R after 6 bars still win 13–19 % of the time with an eventual expectancy of −0.7 to −0.8 R, i.e. they are already mostly lost but not reliably so (TIME_TO_STOP.md).\n- No policy passes the pre-registered gate on any population (HOLDOUT_RESULTS.md).\n`; W('EXIT_POLICY_COMPARISON.md', md); }
W('CAPITAL_HARVEST_DIAGNOSTIC.md', `# CAPITAL HARVEST DIAGNOSTIC (connection to the 2026-09-30 Capital Harvest Master study, used as evidence only; nothing re-enabled)\n\nThe earlier Capital Harvest Master (handoff/CAPITAL_HARVEST_MASTER) rejected every adaptive HOLD / PROTECT / HARVEST / EXIT candidate: stress-negative, DD > 30 %, CONTROL beat every candidate on the production monetary stack. V5 tests the same idea in pure R terms with the simplest possible mechanism (ratchet to MFE − gap once armed), on the frozen entries, with no monetary targets.\n\n| Population | Control exit HOLD exp / PF / DD | HARVEST a1 g0.5 HOLD exp / PF / DD | Win rate control → harvest | Avg winner control → harvest | Right-tail mean realized control → harvest (ratio) | Tail trades truncated (< 1 R) | Profit lost on tail (R) | Stress exp control → harvest | DEV exp control → harvest |\n|---|---|---|---|---|---|---|---|---|---|\n${MEAN.map((pop) => { const c = R.finalists.HOLD[pop].CONTROL_EXIT, h = R.finalists.HOLD[pop].HARVEST, dc = R.finalists.DEV[pop].CONTROL_EXIT, dh = R.finalists.DEV[pop].HARVEST; return `| ${pop} | ${f(c.expectancy_r)} / ${f(c.pf, 2)} / ${f(c.max_dd_r, 1)} | ${f(h.expectancy_r)} / ${f(h.pf, 2)} / ${f(h.max_dd_r, 1)} | ${pc(c.win_rate)} → ${pc(h.win_rate)} | ${f(c.avg_win_r, 2)} → ${f(h.avg_win_r, 2)} | ${f(h.right_tail.control_mean_realized_r, 2)} → ${f(h.right_tail.policy_mean_realized_r, 2)} (${f(h.right_tail.ratio, 2)}) | ${pc(h.right_tail.truncation_rate)} | ${f(h.right_tail.profit_lost_r, 0)} | ${f(c.stress.expectancy_r)} → ${f(h.stress.expectancy_r)} | ${f(dc.expectancy_r)} → ${f(dh.expectancy_r)} |`; }).join('\n')}\n\n## Reading\nAdaptive protection improves expectancy on three of four populations in R terms and reduces drawdown by half — exactly the "higher win rate, smaller average winner" profile the directive warns about. It achieves the improvement by giving back less on trades that reverse after +1 R (give-back on MFE ≥ 1 R trades falls from ${f(R.finalists.HOLD.CONTROL.CONTROL_EXIT.giveback[1].mean_giveback_r, 2)} R to ${f(R.finalists.HOLD.CONTROL.HARVEST.giveback[1].mean_giveback_r, 2)} R on CONTROL) at the cost of a third of the right tail. Under stress costs the many small protected exits erase the gain (CONTROL −0.012 R). The result is the same as the Capital Harvest Master's: management reshapes the distribution, it does not create expectancy; a positive point estimate that depends on normal costs, truncates > 2 R winners and has a session-block CI through zero is REJECTED by the pre-registered gate. Capital Harvest is not re-enabled.\n`);

// ---------- time / give-back / right tail ----------
{ let md = `# TIME TO MFE (bars from entry to the first touch of each milestone on the open path; winners / losers under the control exit; "after adverse" = eventual winners whose MAE ≥ 0.5 R)\n`; for (const S of S2) { md += `\n## ${S}\n| Population | Milestone | Winners median bars | Losers median bars | Winners-after-adverse median bars | Winners reaching | Losers reaching |\n|---|---|---|---|---|---|---|\n`; for (const pop of MEAN) for (const [m, v] of Object.entries(R[S].diagnostics[pop].time_to_mfe)) md += `| ${pop} | ${m} R | ${f(v.winners_median_bars)} | ${f(v.losers_median_bars)} | ${f(v.winners_after_adverse_median_bars)} | ${pc(v.winners_reaching)} | ${pc(v.losers_reaching)} |\n`; }
  md += `\n## Reading\nWinners and losers reach +0.25 / +0.5 / +1 R at the same speed (CONTROL medians 1 / 2 / 5 bars for winners vs 1 / 2 / 4 bars for losers): speed to a milestone carries no information about the eventual outcome. Eventual winners that first went ≥ 0.5 R against entry take 1.5–2× longer to reach each milestone, so "slow" is not "bad". No time-based exit is supported by this table, and none was created.\n`; W('TIME_TO_MFE.md', md); }
{ let md = `# TIME TO STOP (losing trades under the control exit by bars to invalidation: FAST ≤ 3, MEDIUM 4–12, SLOW 13–48, LATE > 48; TEMPORARY_ADVERSE = loser that first reached +0.5 R)\n`; for (const S of S2) { md += `\n## ${S}\n| Population | Speed class | N | Share of losers | Temporary-adverse share | Mean MFE before loss (R) | Losers median bars | Winners median bars |\n|---|---|---|---|---|---|---|---|\n`; for (const pop of MEAN) { const t = R[S].diagnostics[pop].time_to_stop; const tot = Object.values(t.losers_by_speed).reduce((a, v) => a + v.n, 0); for (const [k, v] of Object.entries(t.losers_by_speed)) md += `| ${pop} | ${k} | ${v.n} | ${pc(v.n / tot)} | ${pc(v.temporary_adverse_share)} | ${f(v.mfe_r, 2)} | ${t.losers_median_bars} | ${t.winners_median_bars} |\n`; } md += `\n| Population | Trades at ≤ −0.5 R after 3 bars (n / of open) | Their eventual expectancy (R) / win rate | At ≤ −0.5 R after 6 bars | Eventual expectancy / win rate |\n|---|---|---|---|---|\n`; for (const pop of MEAN) { const h = R[S].diagnostics[pop].time_to_stop.at_minus_half_r_after; md += `| ${pop} | ${h[3].n_at_minus_half} / ${h[3].n_open} | ${f(h[3].eventual_expectancy_r)} / ${pc(h[3].eventual_win_rate)} | ${h[6].n_at_minus_half} / ${h[6].n_open} | ${f(h[6].eventual_expectancy_r)} / ${pc(h[6].eventual_win_rate)} |\n`; } }
  const c = R.HOLD.diagnostics.CONTROL.time_to_stop; md += `\n## Reading\nFast failures (≤ 3 bars, ${pc(c.losers_by_speed['FAST_<=3'].n / Object.values(c.losers_by_speed).reduce((a, v) => a + v.n, 0))} of CONTROL HOLD losers) are genuine wrong-direction entries (MFE ${f(c.losers_by_speed['FAST_<=3'].mfe_r, 2)} R); slow and late failures (${pc((c.losers_by_speed['SLOW_13-48'].n + c.losers_by_speed['LATE_>48'].n) / Object.values(c.losers_by_speed).reduce((a, v) => a + v.n, 0))}) were mostly in profit first (temporary-adverse ${pc(c.losers_by_speed['SLOW_13-48'].temporary_adverse_share)} / ${pc(c.losers_by_speed['LATE_>48'].temporary_adverse_share)}). A trade at −0.5 R after 6 bars still wins ${pc(c.at_minus_half_r_after[6].eventual_win_rate)} of the time with an eventual expectancy of ${f(c.at_minus_half_r_after[6].eventual_expectancy_r)} R — cutting it at −0.5 R saves ~0.3 R per such trade but the TIME family's sequential result is negative on every population (EXIT_POLICY_COMPARISON.md) because the freed capital re-enters the same losing stream. Fast failure does not justify an earlier exit rule on this evidence.\n`; W('TIME_TO_STOP.md', md); }
{ let md = `# PROFIT GIVE-BACK (trades with MFE ≥ threshold: give-back = MFE − realized; control exit and finalist policies)\n`; for (const S of S2) { md += `\n## ${S}\n| Population | Policy | MFE ≥ | N (share) | Mean MFE (R) | Mean realized (R) | Mean give-back (R) | Share ending as losers |\n|---|---|---|---|---|---|---|---|\n`; for (const pop of MEAN) for (const [fam, v] of Object.entries(R.finalists[S][pop])) { if (!v) continue; for (const th of ['0.5', '0.75', '1', '1.5', '2']) { const g = v.giveback[th]; md += `| ${pop} | ${fam === 'CONTROL_EXIT' ? 'control exit' : v.key} | ${th} R | ${g.n} (${pc(g.share)}) | ${f(g.mean_mfe_r, 2)} | ${f(g.mean_realized_r, 2)} | ${f(g.mean_giveback_r, 2)} | ${pc(g.losers_share)} |\n`; } } }
  const g = R.finalists.HOLD.CONTROL.CONTROL_EXIT.giveback; md += `\n## Reading\nGive-back is systematic and large under the control exit: trades that reach +1 R give back ${f(g[1].mean_giveback_r, 2)} R on average and ${pc(g[1].losers_share)} of them end as losers; trades that reach +2 R give back ${f(g[2].mean_giveback_r, 2)} R (because the objective TP2 often sits at 2–3 R). The harvest policy cuts the +1 R give-back to ${f(R.finalists.HOLD.CONTROL.HARVEST.giveback[1].mean_giveback_r, 2)} R and the loser share to ${pc(R.finalists.HOLD.CONTROL.HARVEST.giveback[1].losers_share)}, which is where its expectancy gain comes from — and it does so by also capping the trades that would have continued (RIGHT_TAIL_ANALYSIS.md). PROFIT_GIVEBACK_RESULT = SYSTEMATIC (≈ 1.4 R on +1 R trades) but not exploitable without truncating the tail or failing stress costs.\n`; W('PROFIT_GIVEBACK.md', md); }
{ let md = `# RIGHT-TAIL ANALYSIS (trades whose OPEN-path MFE ≥ 2 R; mean realized under each policy vs the control exit; truncation = realized < 1 R; PRESERVED = ratio ≥ 0.80, INCONCLUSIVE 0.60–0.80, NO < 0.60)\n`; for (const S of S2) { md += `\n## ${S}\n| Population | Policy | Tail trades (share of signals) | Control mean realized (R) | Policy mean realized (R) | Ratio | Truncation rate | Profit lost vs control (R) | Verdict |\n|---|---|---|---|---|---|---|---|---|\n`; for (const pop of MEAN) for (const [fam, v] of Object.entries(R.finalists[S][pop])) { if (!v || fam === 'CONTROL_EXIT') continue; const t = v.right_tail; md += `| ${pop} | ${v.key} | ${t.tail_trades} (${pc(t.tail_share)}) | ${f(t.control_mean_realized_r, 2)} | ${f(t.policy_mean_realized_r, 2)} | ${f(t.ratio, 2)} | ${pc(t.truncation_rate)} | ${f(t.profit_lost_r, 0)} | ${t.verdict} |\n`; } }
  md += `\n## Reading\n${pc(R.finalists.HOLD.CONTROL.CONTROL_EXIT.right_tail.tail_share)} of CONTROL signals eventually run ≥ 2 R. The control exit realizes ${f(R.finalists.HOLD.CONTROL.CONTROL_EXIT.right_tail.control_mean_realized_r, 2)} R on them (TP2 at 2–3 R). Break-even / partial / floor policies realize 0.64–0.75 of that; the adaptive harvest 0.67 (${pc(R.finalists.HOLD.CONTROL.HARVEST.right_tail.truncation_rate)} of tail trades end below 1 R); the structural trail and 3 R target realize MORE than the control (ratio 1.1–1.3) but lose that advantage on the non-tail trades. No policy both preserves the tail AND improves expectancy with a CI above zero. RIGHT_TAIL_PRESERVED for the best-expectancy policy (CONTROL × HARVEST a1 g0.5) = ${R.finalists.HOLD.CONTROL.HARVEST.right_tail.verdict}.\n`; W('RIGHT_TAIL_ANALYSIS.md', md); }

// ---------- matrices ----------
{ let md = `# ENTRY × GEOMETRY MATRIX (ENTRY TYPE × ENTRY TIMING × SL-distance tercile; control exit; cells with N < 30 omitted; reach = milestone before invalidation)\n`; for (const S of S2) for (const pop of MEAN) { const M = R[S].diagnostics[pop].entry_geometry_matrix; md += `\n## ${S} — ${POPNAME[pop]} (risk/ATR tercile cuts ${M.risk_cuts_atr.join(' / ')})\n| Cell (model | timing | SL) | N | Exp (R) | PF | Win | Avg win / loss (R) | DD (R) | MFE / MAE (R) | Reach 1 R | Reach 1.7 R | Reach 2 R |\n|---|---|---|---|---|---|---|---|---|---|---|---|\n`; for (const [k, v] of Object.entries(M.cells)) { if (v.n < 30) continue; md += `| ${k} | ${v.n} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${pc(v.win_rate)} | ${f(v.avg_win_r, 2)} / ${f(v.avg_loss_r, 2)} | ${f(v.max_dd_r, 1)} | ${f(v.mfe_r, 2)} / ${f(v.mae_r, 2)} | ${pc(v.reach_1r)} | ${pc(v.reach_1_7r)} | ${pc(v.reach_2r)} |\n`; } }
  md += `\n## Reading\nThe only cell pattern that repeats across populations and splits is SL distance: the widest-stop tercile is the least negative or mildly positive (CONTROL BO|CHASED|SL_HIGH HOLD ${f(R.HOLD.diagnostics.CONTROL.entry_geometry_matrix.cells['BO|CHASED|SL_HIGH']?.expectancy_r)} R vs SL_LOW ${f(R.HOLD.diagnostics.CONTROL.entry_geometry_matrix.cells['BO|CHASED|SL_LOW']?.expectancy_r)} R), while target reach is nearly identical across stop terciles (reach 1 R ≈ 53–58 %). Wider stops lose less often, not because the setup is better but because fewer winners are shaken out; this is the same information as MAE_ANALYSIS.md and does not translate into a rule (widening every stop by 1.25 × is negative, STRUCTURAL_STOP_ANALYSIS.md). No timing × geometry cell with N ≥ 100 is positive with a CI above zero.\n`; W('ENTRY_GEOMETRY_MATRIX.md', md); }
{ let md = `# MODEL × GEOMETRY MATRIX (production models inside CONTROL; V4 families as separate populations; control exit; open-path MFE and reach)\n`; for (const S of S2) { md += `\n## ${S}\n| Population | Model | N | Risk / ATR median | Open MFE median (R) | MAE median (R) | Reach 1 R | Reach 1.7 R | Reach 2 R | Exp (R) | PF | Win | Avg win / loss (R) | Best fixed RR on DEV (exp) |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|\n`; for (const pop of ALLPOP) for (const [m, v] of Object.entries(R[S].diagnostics[pop].model_geometry)) { const best = Object.entries(R.DEV.grid[pop]).filter(([k]) => k.startsWith('FIXED')).sort((a, b) => b[1].expectancy_r - a[1].expectancy_r)[0]; md += `| ${pop} | ${m} | ${v.n} | ${f(v.risk_atr_median, 2)} | ${f(v.mfe_open_median, 2)} | ${f(v.mae_median, 2)} | ${pc(v.reach_1r)} | ${pc(v.reach_1_7r)} | ${pc(v.reach_2r)} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${pc(v.win_rate)} | ${f(v.avg_win_r, 2)} / ${f(v.avg_loss_r, 2)} | ${best ? `${best[0]} (${f(best[1].expectancy_r)})` : '—'} |\n`; } }
  md += `\n## Reading\nSetup types differ in stop width (SR 0.87 ATR, MR 1.0, BO 1.3, PB 1.7, MC 2.5, V4 first-break 2.3 ATR) and barely in reach (1 R before invalidation 50–57 % for every model and family except MR 67 % on 229 trades; 1.7 R 39–50 %). The DEV-best fixed RR differs by population (CONTROL 3.0, S2 1.25, S3 3.0, S4 3.0) and none of those choices holds on HOLDOUT with a CI above zero. Different setup types do NOT reveal materially different natural geometry; assigning separate RR per model would be fitting noise (not done).\n`; W('MODEL_GEOMETRY_MATRIX.md', md); }
{ let md = `# REGIME × GEOMETRY MATRIX (5m regime at entry; control exit; stop reach and open-path reach)\n`; for (const S of S2) { md += `\n## ${S}\n| Population | Regime | N | Risk / ATR | Open MFE median | MAE median | Stop reach | Reach 1 R | Reach 1.7 R | Exp (R) | PF | Median bars |\n|---|---|---|---|---|---|---|---|---|---|---|---|\n`; for (const pop of MEAN) for (const [k, v] of Object.entries(R[S].diagnostics[pop].regime_geometry)) md += `| ${pop} | ${k} | ${v.n} | ${f(v.risk_atr_median, 2)} | ${f(v.mfe_open_median, 2)} | ${f(v.mae_median, 2)} | ${pc(v.stop_reach)} | ${pc(v.reach_1r)} | ${pc(v.reach_1_7r)} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${f(v.median_bars)} |\n`; }
  md += `\n## Reading\nMAE, MFE, stop reach and duration vary by less than 0.2 R / 10 points across regimes. Expectancy differences by regime (TRANSITION and HIGH_VOLATILITY worst, BEAR_TREND and RANGE best in both CONTROL and S3 on HOLD) are driven by direction/win-rate, not geometry, and they did not hold across splits in V3. Geometry is not regime-dependent to a degree that would justify regime-specific exits; none were created.\n`; W('REGIME_GEOMETRY_MATRIX.md', md); }
{ let md = `# DIRECTION × GEOMETRY (BUY and SELL separately; control exit)\n`; for (const S of S2) { md += `\n## ${S}\n| Population | Side | N | Risk / ATR | Open MFE median | MAE median | Stop reach | Reach 1 R | Reach 1.7 R | Reach 2 R | Exp (R) | PF | Win | Median bars |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|\n`; for (const pop of ALLPOP) for (const [k, v] of Object.entries(R[S].diagnostics[pop].direction_geometry)) md += `| ${pop} | ${k} | ${v.n} | ${f(v.risk_atr_median, 2)} | ${f(v.mfe_open_median, 2)} | ${f(v.mae_median, 2)} | ${pc(v.stop_reach)} | ${pc(v.reach_1r)} | ${pc(v.reach_1_7r)} | ${pc(v.reach_2r)} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${pc(v.win_rate)} | ${f(v.median_bars)} |\n`; }
  md += `\n## Reading\nOn HOLDOUT, SELL entries reach every milestone 3–5 points more often than BUY entries and have ~3 points lower stop reach, in both CONTROL (SELL ${f(R.HOLD.diagnostics.CONTROL.direction_geometry.SELL.expectancy_r)} R vs BUY ${f(R.HOLD.diagnostics.CONTROL.direction_geometry.BUY.expectancy_r)} R) and S3; BUY trades also pay the spread on entry and the overnight swap. On DEV the asymmetry was smaller or reversed (V4 DIRECTIONAL_ANALYSIS.md). MFE/MAE in R are symmetric within 0.1 R. The asymmetry is in direction accuracy, not in geometry; no directional geometry rule is supportable.\n`; W('DIRECTION_GEOMETRY.md', md); }

// ---------- cost / capital ----------
W('COST_STRESS.md', `# COST STRESS (NORMAL 0.24 + 0.10; STRESS 0.60 + 0.20; DRIFT next-open fill; finalist policies per population)\n\n| Split | Population | Policy | Trades | Gross exp (USD @0.01) | Cost USD/trade | Cost share of gross | Net exp (R) | Net exp (USD) | PF | DD (R) | Stress exp (R) | Stress PF | Stress DD (R) | Drift exp (R) |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|\n${S2.flatMap((S) => MEAN.flatMap((pop) => Object.entries(R.finalists[S][pop]).filter(([, v]) => v).map(([fam, v]) => `| ${S} | ${pop} | ${fam === 'CONTROL_EXIT' ? 'control exit' : v.key} | ${v.n} | ${f(v.gross_expectancy_usd, 2)} | ${f(v.cost_usd, 2)} | ${pc(v.cost_pct_gross)} | ${f(v.expectancy_r)} | ${f(v.expectancy_usd, 2)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 1)} | ${f(v.stress.expectancy_r)} | ${f(v.stress.pf, 2)} | ${f(v.stress.max_dd_r, 1)} | ${f(v.drift.expectancy_r)} |`))).join('\n')}\n\n## Reading\nCosts are 3–6 % of 1R for these stop sizes (0.34 USD per trade against a median risk of 8–12 USD at 0.01 lot), so NORMAL costs do not decide anything. STRESS costs (0.80 USD per trade) do: every protection/harvest policy that is positive at normal cost is negative at stress cost because it exits more often and closer to entry (CONTROL HARVEST +0.077 → −0.012 R; S2 HARVEST +0.061 → −0.032 R). Only the 3 R target on S3 stays positive under stress (+0.016 R) and it fails everything else. Any policy that works only before costs is rejected — that is all of them.\n`);
{ let md = `# CAPITAL SURVIVAL (0.01 lot; sequential HOLDOUT paths; month-shuffle resampling 500 draws; diagnostics, not decision inputs)\n\n| Population | Policy | Trades | Net USD | Max DD USD | Max DD R | Loss streak | Trades to new high (max) | Mean risk USD | Mean broker-SL USD | Adverse DD USD p50 / p90 / p99 | Adverse loss streak p50 / p90 |\n|---|---|---|---|---|---|---|---|---|---|---|---|\n`; for (const pop of MEAN) for (const [fam, v] of Object.entries(R.finalists.HOLD[pop])) { if (!v) continue; const c = v.capital, a = v.adverse; md += `| ${pop} | ${fam === 'CONTROL_EXIT' ? 'control exit' : v.key} | ${c.trades} | ${f(c.net_usd, 0)} | ${f(c.max_dd_usd, 0)} | ${f(v.max_dd_r, 1)} | ${c.max_loss_streak} | ${c.trades_to_new_high_max} | ${f(c.mean_risk_usd, 2)} | ${f(c.mean_broker_sl_usd, 2)} | ${f(a.dd_usd_p50, 0)} / ${f(a.dd_usd_p90, 0)} / ${f(a.dd_usd_p99, 0)} | ${a.loss_streak_p50} / ${a.loss_streak_p90} |\n`; }
  md += `\n## Small-capital translation (same geometry, 0.01 lot; margin ≈ price × 100 × 0.01 / 200)\n| Population | Policy | Capital | Max DD % of capital | Mean broker-SL risk % | Margin % | P(DD > 25 %) | P(DD > 50 %) | MARGIN_SAFETY_VETO blocks execution |\n|---|---|---|---|---|---|---|---|---|\n`; for (const pop of ['CONTROL', 'S3']) for (const fam of ['CONTROL_EXIT', BEST.pop === pop ? BEST.family : 'HARVEST']) { const v = R.finalists.HOLD[pop][fam]; if (!v) continue; for (const cap of ['62', '100', '1000', '10000']) { const b = v.capital.by_capital[cap], p = v.adverse.dd_usd_samples_p[cap]; md += `| ${pop} | ${fam === 'CONTROL_EXIT' ? 'control exit' : v.key} | $${cap} | ${pc(b.max_dd_pct)} | ${pc(b.risk_pct_mean)} | ${pc(b.margin_pct)} | ${pc(p.p_dd_gt_25pct)} | ${pc(p.p_dd_gt_50pct)} | ${b.margin_safety_veto_blocks ? 'YES (equity < ≈71 USD)' : 'no'} |\n`; } }
  md += `\n## Reading\nAt 0.01 lot the HOLDOUT max drawdown of the control exit is ${f(HC.capital.max_dd_usd, 0)} USD (${f(HC.max_dd_r, 0)} R; adverse resampling p90 ${f(HC.adverse.dd_usd_p90, 0)} USD) with a ${HC.capital.max_loss_streak}-trade losing streak and up to ${HC.capital.trades_to_new_high_max} trades without a new equity high. That is ${pc(HC.capital.by_capital['62'].max_dd_pct)} of a $62 account and ${pc(HC.capital.by_capital['100'].max_dd_pct)} of $100: both are wiped out with probability 1 under resampling, and the $62 account is in any case blocked by the production MARGIN_SAFETY_VETO (needs ≈ 71 USD equity for one 0.01 lot). At $1,000 the drawdown is ${pc(HC.capital.by_capital['1000'].max_dd_pct)} of capital (P(DD > 50 %) ${pc(HC.adverse.dd_usd_samples_p['1000'].p_dd_gt_50pct)}); at $10,000 it is ${pc(HC.capital.by_capital['10000'].max_dd_pct)} — survivable, but with negative expectancy survival only slows the loss. The best research policy halves the drawdown (${f(HB.capital.max_dd_usd, 0)} USD) without changing the conclusion. No research conclusion was altered for the $62 account.\n`; W('CAPITAL_SURVIVAL.md', md); }

// ---------- results ----------
W('FROZEN_FINALISTS.md', `# FROZEN FINALISTS\n\n\`configs/finalists.json\` sha256 **${R.finalists_sha256}**, derived from DEV only (best DEV sequential expectancy per population × family with N ≥ 200; ties → the parameter closest to CONTROL), frozen before HOLDOUT was opened (results/dev_phase_console.txt → results/full_phase_console.txt).\n\n| Population | Family | Policy | DEV N | DEV exp (R) | DEV PF | DEV DD (R) | Control exit DEV exp | Beats control on DEV |\n|---|---|---|---|---|---|---|---|---|\n${MEAN.flatMap((pop) => FAMS.map((fam) => { const v = DEFN.finalists[pop][fam]; return v ? `| ${pop} | ${fam} | ${v.key} | ${v.dev_n} | ${f(v.dev_expectancy_r)} | ${f(v.dev_pf, 2)} | ${f(v.dev_dd_r, 1)} | ${f(v.control_dev_expectancy_r)} | ${v.beats_control_dev ? 'yes' : 'no'} |` : `| ${pop} | ${fam} | — | | | | | | |`; })).join('\n')}\n\nBaselines: B0 = control exit; B1 = FIXED; B2 = best of BE / PARTIAL / FLOOR; B3 = STRUCT_TRAIL; B4 = HARVEST; T = time-stop (diagnostic). Only two (population, family) pairs were positive on DEV with a PF > 1.05: CONTROL × STRUCT_TRAIL (+0.113 R) and CONTROL × HARVEST (+0.041 R); every other finalist was carried to HOLDOUT once as pre-registered.\n`);
W('DEVELOPMENT_RESULTS.md', `# DEVELOPMENT RESULTS (2025-05-07 → 2025-12-31; sequential; NORMAL costs; finalist policies and control exits)\n\n| Population | Policy | Trades | Win | Avg win / loss (R) | Exp (R) | PF | DD (R) | 95 % CI | Stress exp | Right tail ratio | Give-back (R) |\n|---|---|---|---|---|---|---|---|---|---|---|---|\n${MEAN.flatMap((pop) => Object.entries(R.finalists.DEV[pop]).filter(([, v]) => v).map(([fam, v]) => `| ${pop} | ${fam === 'CONTROL_EXIT' ? 'control exit' : v.key} | ${v.n} | ${pc(v.win_rate)} | ${f(v.avg_win_r, 2)} / ${f(v.avg_loss_r, 2)} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 1)} | ${ci(v.ci95_r)} | ${f(v.stress.expectancy_r)} | ${f(v.right_tail.ratio, 2)} | ${f(v.giveback_r_mean, 2)} |`)).join('\n')}\n\nFull DEV policy grids per population: see EXIT_POLICY_COMPARISON.md (HOLD grids) and results/v5_results_DEV_phase.json.\n`);
W('HOLDOUT_RESULTS.md', `# HOLDOUT RESULTS (2026-01-01 → 2026-09-29; opened once after configs/finalists.json was hashed; sequential; NORMAL costs)\n\n| Population | Policy | Trades | Win | Avg win / loss (R) | Exp (R) | Exp (USD @0.01) | PF | DD (R) | Trade 95 % CI | Block 95 % CI | 99 % CI | Stress exp | Drift exp | Quarters > 0 | Right tail | Δ vs control exit |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|\n${MEAN.flatMap((pop) => Object.entries(R.finalists.HOLD[pop]).filter(([, v]) => v).map(([fam, v]) => { const ctl = R.finalists.HOLD[pop].CONTROL_EXIT; return `| ${pop} | ${fam === 'CONTROL_EXIT' ? 'control exit' : v.key} | ${v.n} | ${pc(v.win_rate)} | ${f(v.avg_win_r, 2)} / ${f(v.avg_loss_r, 2)} | ${f(v.expectancy_r)} | ${f(v.expectancy_usd, 2)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 1)} | ${ci(v.ci95_r)} | ${ci(v.block_ci95_r)} | ${ci(v.ci99_r)} | ${f(v.stress.expectancy_r)} | ${f(v.drift.expectancy_r)} | ${pc(v.quarters_positive_share)} | ${f(v.right_tail.ratio, 2)} ${v.right_tail.verdict} | ${fam === 'CONTROL_EXIT' ? '—' : f(v.expectancy_r - ctl.expectancy_r)} |`; })).join('\n')}\n\n## Gate decisions (V5_PREREGISTRATION.md §7)\n| Population | Family | Policy | Status | Failed items |\n|---|---|---|---|---|\n${MEAN.flatMap((pop) => Object.entries(DEC.by_population[pop].policies).map(([fam, d]) => `| ${pop} | ${fam} | ${d.key} | ${d.status} | ${d.reasons.join('; ') || '—'} |`)).join('\n')}\n\nPassing policies: ${DEC.passing.length ? DEC.passing.join(', ') : 'none'}. Best by HOLDOUT expectancy with N ≥ 200: **${BEST.pop} × ${BEST.key}** (${f(BEST.hold_expectancy_r)} R, PF ${f(BEST.hold_pf, 2)}, DD ${f(BEST.hold_dd_r, 1)} R, trade CI ${ci(BEST.ci95_r)}, block CI ${ci(BEST.block_ci95_r)}, improvement ${f(BEST.improvement_r)} R over its control exit, right tail ${BEST.right_tail}). ENTRY_ECONOMICS_RESULT = ${DEC.entry_economics_result}; EXIT_GEOMETRY_RESULT = ${DEC.exit_geometry_result}; EDGE_DEMONSTRATED = ${DEC.edge_demonstrated}; CONTROL_VS_V5 = ${DEC.control_vs_v5}; DEMO_ELIGIBLE = ${DEC.demo_eligible}.\n`);
W('WALK_FORWARD_RESULTS.md', `# WALK-FORWARD RESULTS (calendar quarters; sequential; NORMAL costs; finalists and control exits)\n\n${S2.map((S) => `## ${S}\n| Population | Policy | ${Object.keys(R.finalists[S].CONTROL.CONTROL_EXIT.walk_forward).join(' | ')} | Quarters > 0 |\n|---|---|${Object.keys(R.finalists[S].CONTROL.CONTROL_EXIT.walk_forward).map(() => '---|').join('')}---|\n${MEAN.flatMap((pop) => Object.entries(R.finalists[S][pop]).filter(([, v]) => v).map(([fam, v]) => `| ${pop} | ${fam === 'CONTROL_EXIT' ? 'control exit' : v.key} | ${Object.keys(R.finalists[S].CONTROL.CONTROL_EXIT.walk_forward).map((q) => { const x = v.walk_forward[q]; return x ? `n ${x.n}, ${f(x.expectancy_r)} R, PF ${f(x.pf, 2)}, DD ${f(x.max_dd_r, 0)}, W/L ${f(x.avg_win_r, 2)}/${f(x.avg_loss_r, 2)}, GB ${f(x.giveback_r_mean, 2)}` : '—'; }).join(' | ')} | ${pc(v.quarters_positive_share)} |`)).join('\n')}\n`).join('\n')}\n## Reading\nThe CONTROL × HARVEST policy is the only one positive in all three HOLDOUT quarters (+0.02 / +0.17 / +0.03 R), with two of three DEV quarters positive; its 2026Q2 result carries the year. Every other policy alternates sign by quarter exactly as its control exit does. No policy is period-robust in the sense of the gate except the harvest, which fails the gate on stress, right tail, neighbourhood and the block CI.\n`);
W('PARAMETER_STABILITY.md', `# PARAMETER STABILITY (pre-registered grid neighbours per family; HOLDOUT and DEV; ROBUST = all neighbours positive, SENSITIVE = some ≤ 0, FRAGILE = only centre positive, NEGATIVE_CENTRE)\n\n${MEAN.map((pop) => `## ${POPNAME[pop]}\n${FAMS.map((fam) => { const h = R.finalists.HOLD[pop][fam], d = R.finalists.DEV[pop][fam]; if (!h) return `**${fam}** — no finalist.`; const nh = h.neighbourhood, nd = d.neighbourhood; return `**${fam}** (selected ${h.key}) — HOLD ${nh.classification}: ${Object.entries(nh).filter(([k]) => k !== 'classification').map(([k, x]) => `${k} → n ${x.n}, ${f(x.expectancy_r)} R, PF ${f(x.pf, 2)}`).join('; ')}. DEV ${nd.classification}: ${Object.entries(nd).filter(([k]) => k !== 'classification').map(([k, x]) => `${k} → ${f(x.expectancy_r)} R`).join('; ')}.`; }).join('\n\n')}\n`).join('\n')}\n## Reading\nThe harvest family on CONTROL is ROBUST on DEV (all six grid points positive) and SENSITIVE on HOLD (a1 g1 −0.017 R; the 0.5 R gap is the only clearly positive gap). Fixed targets are NEGATIVE_CENTRE everywhere except S3 (SENSITIVE: only 3 R positive). Milestone protection families are NEGATIVE_CENTRE on every population. Broad stable regions exist only in the negative.\n`);
W('UNCERTAINTY_ANALYSIS.md', `# UNCERTAINTY ANALYSIS (trade bootstrap 2,000 draws seed 20260930; session-block bootstrap 2,000 draws seed 7; month-shuffle adverse sequencing 500 draws; HOLDOUT finalists)\n\n| Population | Policy | N | Exp (R) | Trade 95 % CI | Trade 99 % CI | Block 95 % CI | Block 99 % CI | PF | Max loss streak | Adverse DD R p50 / p90 | Adverse loss streak p50 / p90 | Top-5 winners share |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|\n${MEAN.flatMap((pop) => Object.entries(R.finalists.HOLD[pop]).filter(([, v]) => v).map(([fam, v]) => `| ${pop} | ${fam === 'CONTROL_EXIT' ? 'control exit' : v.key} | ${v.n} | ${f(v.expectancy_r)} | ${ci(v.ci95_r)} | ${ci(v.ci99_r)} | ${ci(v.block_ci95_r)} | ${ci(v.block_ci99_r)} | ${f(v.pf, 2)} | ${v.max_loss_streak} | ${f(v.adverse.dd_r_p50, 1)} / ${f(v.adverse.dd_r_p90, 1)} | ${v.adverse.loss_streak_p50} / ${v.adverse.loss_streak_p90} | ${pc(v.top5_share)} |`)).join('\n')}\n\n## Reading\nThe only policy whose trade-bootstrap 95 % CI excludes zero is CONTROL × HARVEST a1 g0.5 (${ci(HB.ci95_r)}); its session-block CI (${ci(HB.block_ci95_r)}) and 99 % CI (${ci(HB.ci99_r)}) include zero, and it was selected from 27 policies × 4 populations (Bonferroni). Every control exit has a CI through zero with a negative point estimate. No candidate's apparent edge survives the uncertainty the pre-registration demanded.\n`);
W('CONTROL_VS_V5.md', `# CONTROL vs V5 (HOLDOUT, sequential, NORMAL costs) — four-way isolation of where improvement originates\n\n| Combination | Policy | Trades | Exp (R) | PF | DD (R) | Trade 95 % CI | Win | Avg win / loss (R) |\n|---|---|---|---|---|---|---|---|---|\n${Object.entries(DEC.four_way).map(([k, v]) => `| ${k} | ${v.key} | ${v.n} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 1)} | ${ci(v.ci95_r)} | ${pc(v.win_rate)} | ${f(v.avg_win_r, 2)} / ${f(v.avg_loss_r, 2)} |`).join('\n')}\n\n| Metric | CONTROL (production entry + exit) | Best V5 (${BEST.pop} × ${BEST.key}) |\n|---|---|---|\n| Trades | ${HC.n} | ${HB.n} |\n| Expectancy (R) | ${f(HC.expectancy_r)} | ${f(HB.expectancy_r)} |\n| PF | ${f(HC.pf, 2)} | ${f(HB.pf, 2)} |\n| Max DD (R / USD @0.01) | ${f(HC.max_dd_r, 1)} / ${f(HC.max_dd_usd, 0)} | ${f(HB.max_dd_r, 1)} / ${f(HB.max_dd_usd, 0)} |\n| Trade / block 95 % CI | ${ci(HC.ci95_r)} / ${ci(HC.block_ci95_r)} | ${ci(HB.ci95_r)} / ${ci(HB.block_ci95_r)} |\n| Stress exp (R) | ${f(HC.stress.expectancy_r)} | ${f(HB.stress.expectancy_r)} |\n| Win rate / avg win / avg loss | ${pc(HC.win_rate)} / ${f(HC.avg_win_r, 2)} / ${f(HC.avg_loss_r, 2)} | ${pc(HB.win_rate)} / ${f(HB.avg_win_r, 2)} / ${f(HB.avg_loss_r, 2)} |\n| Right-tail mean realized (MFE ≥ 2 R) | ${f(HC.right_tail.control_mean_realized_r, 2)} | ${f(HB.right_tail.policy_mean_realized_r, 2)} (ratio ${f(HB.right_tail.ratio, 2)}, ${HB.right_tail.verdict}) |\n| Quarters > 0 | ${pc(HC.quarters_positive_share)} | ${pc(HB.quarters_positive_share)} |\n| DEV exp (R) | ${f(R.finalists.DEV.CONTROL.CONTROL_EXIT.expectancy_r)} | ${f(DB.expectancy_r)} |\n\nCONTROL_VS_V5 = ${DEC.control_vs_v5} under the frozen rule (best policy's trade-CI lower bound ${f(BEST.ci95_r[0])} > CONTROL point estimate ${f(HC.expectancy_r)}, DD lower). Where the improvement originates: entirely from the exit (the entry population is identical, and V4 entries with the same research exits do not do better: S3 best ${f(DEC.four_way.V4_ENTRY_WITH_RESEARCH_EXIT.expectancy_r)} R). The exit's gain is a reshaping of the distribution (win rate 36 → 57 %, average winner 2.26 → 1.16 R) that disappears under stress costs and truncates a third of the right tail; it does not make the entry engine positive in the sense the gate requires. EDGE_DEMONSTRATED = ${DEC.edge_demonstrated}.\n`);
W('ENTRY_ECONOMICS_RESULT.md', `# ENTRY ECONOMICS RESULT = ${DEC.entry_economics_result}\n\nUnder the CONTROL exit on HOLDOUT every meaningful entry population is negative: ${MEAN.map((pop) => { const v = R.finalists.HOLD[pop].CONTROL_EXIT; return `${pop} n ${v.n}, ${f(v.expectancy_r)} R, PF ${f(v.pf, 2)}, CI ${ci(v.ci95_r)}`; }).join('; ')}. The geometry diagnostics locate the problem at the trigger, not in the geometry:\n- Target reach before invalidation is ${pc(R.HOLD.diagnostics.CONTROL.target_reach.overall[1])} at 1 R and ${pc(R.HOLD.diagnostics.CONTROL.target_reach.overall[1.7])} at 1.7 R for CONTROL (S3 ${pc(R.HOLD.diagnostics.S3.target_reach.overall[1])} / ${pc(R.HOLD.diagnostics.S3.target_reach.overall[1.7])}), flat across model, direction, regime, timing, ATR state and session, and below the break-even reach at every RR (RR_GEOMETRY.md).\n- The structural stop is reached in ${pc(R.HOLD.diagnostics.CONTROL.structural_stop.stop_reach_rate)} of trades; tightening or widening it does not help (STRUCTURAL_STOP_ANALYSIS.md); half of the winners first go 0.5 R against entry (MAE_ANALYSIS.md).\n- Entry timing classes have identical reach (ENTRY_LOCATION_ANALYSIS.md): the entries are not "too late", they are wrong ~58–64 % of the time.\n- V4 verification (§3): S3 captures 32.9 % of large moves and still loses because its win rate (41.6 %) × avg win (1.68 R) < loss rate × avg loss (1.25 R) after cost; its MFE/MAE/reach profile is indistinguishable from CONTROL's (MFE median 1.18 vs 1.29 R; MAE 1.16 vs 1.27 R; reach 1 R 54.1 % vs 56.1 %).\n\nConclusion: the market opportunity the engine identifies is real only in the sense that ~40 % of entries run ≥ 2 R; the other ~60 % are wrong-direction or fail before 1 R, and no geometry converts that mix into positive after-cost expectancy. This is an entry problem.\n`);
W('EXIT_GEOMETRY_RESULT.md', `# EXIT GEOMETRY RESULT = ${DEC.exit_geometry_result}\n\n27 exit policies × 4 meaningful entry populations, DEV-selected, one HOLDOUT pass. No policy passes the pre-registered gate. The adaptive harvest (arm 1 R, trail MFE − 0.5 R) on CONTROL entries improves HOLDOUT expectancy by ${f(BEST.improvement_r)} R to ${f(HB.expectancy_r)} R (PF ${f(HB.pf, 2)}, DD ${f(HB.max_dd_r, 1)} R, trade CI ${ci(HB.ci95_r)}) and is positive in all three HOLDOUT quarters and on DEV (+0.041 R) — that is why the result is INCONCLUSIVE rather than NEGATIVE. It fails because: stress costs turn it negative (${f(HB.stress.expectancy_r)} R); it realizes ${f(HB.right_tail.ratio, 2)} of the control exit's right tail and truncates ${pc(HB.right_tail.truncation_rate)} of ≥ 2 R trades (RIGHT_TAIL_PRESERVED = ${HB.right_tail.verdict}); its HOLD neighbourhood is SENSITIVE; its session-block CI includes zero. Milestone protection (BE / partial / floor) and fixed targets are negative or ≈ 0 everywhere; the structural trail preserves the tail but adds nothing on HOLDOUT; time-stops do nothing.\n\nAn exit cannot be credited as an entry edge (§6, §35): the same policy on the V4 populations gives +0.061 (S2), +0.029 (S3) and −0.031 R (S4) — it tracks the entry population's own quality. Where the economics break: at the ~58–64 % of entries that are wrong or fail before +1 R; exit geometry can only redistribute the remaining ~40 %.\n`);
W('TRADE_ECONOMICS_V5_SPEC.md', `# TRADE ECONOMICS V5 — IMPLEMENTATION SPEC (NOT IMPLEMENTED: no policy passed; kept so a future passing exit policy can be ported deterministically)\n\n1. Scope: a protective-stop manager acting on an OPEN production position; entries, RR 1.70 objective, structural SL, lot, News V2, spread, drift, breakers and the broker fail-safe are unchanged.\n2. State per position (serialisable): fill, planned entry, structural stop, risk R, MFE in R (updated at each completed bar from the bar high/low), current protective level, armed flag, raised-bar index.\n3. Rule (the best-researched family, for reference only): once MFE ≥ a R at a completed bar, protective level = fill + (MFE − g) × R, monotone (never lowered), applied by modifying the broker SL after the candle closes; exits intrabar at the level; the structural stop / broker fail-safe remain until the protective level exceeds them.\n4. Information-time: the level set by bar j is sent after j closes and can only fill on bar ≥ j + 1 (replay semantics); no forming-bar data.\n5. Safety: the protective level is never wider than the existing broker SL; MARGIN_SAFETY_VETO, identity, dedup and one-position semantics untouched; mode flag OFF by default in an unwired module (as the existing capitalHarvest module is today).\n6. Parity fixtures before wiring: ≥ 200 live candles → identical MFE sequence, protective levels and exit bars versus replay; broker stop-level distance and partial-fill handling fixtured.\n7. Rollback: single flag; no registry file touched.\n\nStatus: SPEC ONLY. EXIT_GEOMETRY_RESULT = ${DEC.exit_geometry_result}; EDGE_DEMONSTRATED = ${DEC.edge_demonstrated}; nothing was wired or re-enabled.\n`);
console.log('tables written to', OUT);
